<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LaporanSidak — Inspeksi Mendadak Area Plantation</title>
<script src="https://cdnjs.cloudflare.com/ajax/libs/exceljs/4.4.0/exceljs.min.js"></script>
<script src="https://cdnjs.cloudflare.com/ajax/libs/FileSaver.js/2.0.2/FileSaver.min.js"></script>
<style>
  :root{
    --green-1:#8bc34a; --green-2:#6fae3a; --green-3:#5a9430;
    --orange-1:#f5942a; --orange-2:#e8791a;
    --lime:#c6d92a; --teal-1:#1fa2a6; --teal-2:#0f7d80;
    --ink:#1f2b16; --paper:#fffef9;
    --red:#e8544a;
    --radius:22px;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    font-family:"Segoe UI", -apple-system, "Helvetica Neue", Arial, sans-serif;
    background:#ffffff;
    background-attachment:fixed;
    color:var(--ink);
    min-height:100vh;
    padding-bottom:90px;
  }
  .grid-overlay{
    position:fixed; inset:0; pointer-events:none; z-index:0;
    background-image:linear-gradient(rgba(31,43,22,0.04) 1px, transparent 1px),
      linear-gradient(90deg, rgba(31,43,22,0.04) 1px, transparent 1px);
    background-size:34px 34px;
  }
  .wrap{ position:relative; z-index:1; max-width:820px; margin:0 auto; padding:30px 18px 10px; }

  header{ display:flex; align-items:flex-start; gap:14px; margin-bottom:18px; position:relative; }
  .logo-badge{
    flex:0 0 auto; width:66px; height:66px; border-radius:16px;
    background:#fffef9;
    border:1.5px solid #ecebe2;
    display:flex; align-items:center; justify-content:center;
    box-shadow:0 10px 20px rgba(20,40,10,0.12), inset 0 1px 0 rgba(255,255,255,0.6);
    padding:5px;
    overflow:hidden;
  }
  .logo-badge img{ width:100%; height:100%; object-fit:contain; }
  .title-block{flex:1; min-width:0;}
  .title-block h1{ margin:0; font-size:26px; line-height:1.1; color:var(--ink); letter-spacing:-0.4px; }
  .title-block h1 .accent{ color:var(--green-3); }
  .title-block p{ margin:6px 0 0; color:#5c5b4c; font-size:13.5px; line-height:1.4; max-width:52ch; }

  .menu-wrap{ position:relative; flex:0 0 auto; margin-left:auto; }
  .menu-btn{
    width:38px;height:38px;border-radius:50%;
    background:#eef0e2; border:1px solid #e3e2d5;
    color:var(--green-3); display:flex;align-items:center;justify-content:center; cursor:pointer;
  }
  .menu-btn svg{width:19px;height:19px;}
  .menu-btn.active{background:#e4e9d4;}
  .settings-panel{
    display:none; position:absolute; top:46px; right:0; width:300px; max-width:80vw;
    background:var(--paper); border-radius:16px; padding:16px;
    box-shadow:0 18px 40px rgba(20,40,10,0.35); z-index:30;
  }
  .settings-panel.show{ display:block; }
  .settings-panel .sp-title{ font-size:13px; font-weight:800; margin-bottom:10px; }
  .settings-panel label{ font-size:11.5px; font-weight:700; color:#8b8a76; display:block; margin:10px 0 4px; }
  .settings-panel input{
    width:100%; padding:9px 10px; border-radius:9px; border:1.5px solid #ecebe2;
    background:#fbfaf4; font-size:13px; color:var(--ink); outline:none;
  }
  .settings-panel input:focus{ border-color:var(--green-2); background:#fff; }
  .sp-desc{ font-size:12px; color:#8b8a76; line-height:1.5; margin:0; }
  .sp-error{ font-size:12px; color:var(--red); font-weight:700; margin-top:8px; }
  .sp-logout{
    margin-top:8px; width:100%; padding:9px; border:1.5px solid #f0c9c6; border-radius:10px;
    background:#fff; color:var(--red); font-weight:700; font-size:12.5px; cursor:pointer;
  }
  .admin-tag{
    display:inline-block; margin-left:6px; padding:2px 8px; border-radius:999px;
    background:#eaf6ec; color:#2f8f52; font-size:10px; font-weight:800; letter-spacing:0.3px; vertical-align:middle;
  }
  .menu-btn.is-admin{ background:rgba(198,217,42,0.35); border-color:var(--lime); }

  .viewer-note{
    display:flex; align-items:center; gap:9px;
    background:#eef6ea; border:1px solid #d5e8c8;
    color:var(--green-3); font-size:12.5px; font-weight:600; line-height:1.4;
    padding:11px 14px; border-radius:14px; margin-bottom:16px;
  }
  .viewer-note svg{ width:18px;height:18px; flex:0 0 auto; opacity:0.9; }
  .viewer-note.hide{ display:none; }
  .sp-close{
    margin-top:14px; width:100%; padding:9px; border:none; border-radius:10px;
    background:var(--green-3); color:#fff; font-weight:700; font-size:13px; cursor:pointer;
  }

  .card{ background:var(--paper); border:1px solid #ecebe2; border-radius:var(--radius); padding:20px; box-shadow:0 14px 34px rgba(20,40,10,0.10); }

  .add-btn{
    display:flex; align-items:center; justify-content:center; gap:8px;
    width:100%; padding:16px; border:none; border-radius:16px; cursor:pointer;
    background:linear-gradient(160deg, var(--orange-1), var(--orange-2));
    color:#fff; font-weight:800; font-size:15.5px;
    box-shadow:0 10px 22px rgba(232,121,26,0.35);
    margin-bottom:18px;
  }
  .add-btn svg{width:20px;height:20px;}

  .toolbar{ display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap; }
  .search-box{ position:relative; flex:1; min-width:180px; }
  .search-box input{
    width:100%; padding:13px 14px 13px 42px; font-size:14.5px; border-radius:14px;
    border:2px solid #ecebe2; background:#fbfaf4; color:var(--ink); outline:none;
  }
  .search-box input:focus{ border-color:var(--green-2); background:#fff; }
  .search-box svg{ position:absolute; left:14px; top:50%; transform:translateY(-50%); width:17px;height:17px; color:#9a9a86; }
  .export-btn{
    display:flex; align-items:center; gap:7px; padding:0 16px; border:none; border-radius:14px;
    background:var(--teal-2); color:#fff; font-weight:700; font-size:13.5px; cursor:pointer;
  }
  .export-btn svg{width:16px;height:16px;}

  .filter-row{ display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap; }
  .date-filter-row{ display:flex; gap:8px; margin-bottom:16px; flex-wrap:wrap; align-items:center; }
  .date-filter-row .df-field{ flex:1; min-width:140px; }
  .date-filter-row label{ display:block; font-size:10.5px; font-weight:700; color:#8b8a76; text-transform:uppercase; letter-spacing:0.3px; margin-bottom:4px; }
  .date-filter-row input[type="date"], .date-filter-row input[type="month"]{
    width:100%; padding:10px 12px; font-size:13.5px; border-radius:12px;
    border:2px solid #ecebe2; background:#fbfaf4; color:var(--ink); outline:none; font-family:inherit;
  }
  .date-filter-row input[type="date"]:focus, .date-filter-row input[type="month"]:focus{ border-color:var(--green-2); background:#fff; }
  .date-filter-row .df-reset{
    flex:0 0 auto; padding:10px 14px; border:1.5px solid #e3e2d5; background:#fbfaf4; color:#5c5b4c;
    border-radius:12px; font-size:12.5px; font-weight:700; cursor:pointer; align-self:flex-end;
  }
  .chip{
    border:1.5px solid #e3e2d5; background:#fbfaf4; color:#5c5b4c; padding:8px 14px;
    border-radius:999px; font-size:12.5px; font-weight:700; cursor:pointer; user-select:none;
  }
  .chip.active[data-f="all"]{background:var(--ink); border-color:var(--ink); color:#fff;}
  .chip.active[data-f="Open"]{background:var(--orange-2); border-color:var(--orange-2); color:#fff;}
  .chip.active[data-f="Proses"]{background:var(--teal-2); border-color:var(--teal-2); color:#fff;}
  .chip.active[data-f="Selesai"]{background:#2f8f52; border-color:#2f8f52; color:#fff;}

  .results-head{ display:flex; justify-content:space-between; align-items:baseline; margin:22px 2px 12px; color:var(--ink); }
  .results-head h3{ margin:0; font-size:15.5px; font-weight:800; }
  .results-head span{ font-size:12.5px; opacity:0.9; }

  .empty-state{ text-align:center; padding:34px 18px; color:#8b8a76; }
  .empty-state svg{width:44px;height:44px;opacity:0.6;margin-bottom:10px;}
  .empty-state .t1{font-weight:700; margin-bottom:4px;}
  .empty-state .t2{font-size:13px; opacity:0.9;}

  .entry-card{
    background:#fdfcf7; border:1.5px solid #ecebe1; border-radius:18px;
    padding:16px 16px 14px; margin-bottom:12px;
  }
  .ec-top{ display:flex; justify-content:space-between; align-items:flex-start; gap:10px; }
  .ec-no{
    flex:0 0 auto; width:30px;height:30px; border-radius:9px; background:#eef0e2;
    color:var(--green-3); font-weight:800; font-size:13px; display:flex; align-items:center; justify-content:center;
  }
  .ec-heading{ flex:1; min-width:0; }
  .ec-dept{ font-weight:800; font-size:15px; color:var(--ink); }
  .ec-sub{ font-size:12px; color:#8b8a76; margin-top:1px; }
  .status-badge{ flex:0 0 auto; font-size:10.5px; font-weight:800; letter-spacing:0.3px; padding:5px 10px; border-radius:999px; color:#fff; white-space:nowrap; }
  .status-badge.Open{background:var(--orange-2);}
  .status-badge.Proses{background:var(--teal-2);}
  .status-badge.Selesai{background:#2f8f52;}
  .status-badge.none{background:#b2b19f;}

  .ec-grid{ display:grid; grid-template-columns:1fr 1fr; gap:8px 14px; margin-top:12px; font-size:12.5px; }
  .ec-field .lbl{ font-size:10px; text-transform:uppercase; letter-spacing:0.4px; color:#a5a493; font-weight:700; }
  .ec-field .val{ font-size:13px; font-weight:600; color:var(--ink); margin-top:1px; }

  .ec-block{ margin-top:12px; padding-top:10px; border-top:1px dashed #e6e5d9; }
  .ec-block .lbl{ font-size:10px; text-transform:uppercase; letter-spacing:0.4px; color:#a5a493; font-weight:700; margin-bottom:3px; }
  .ec-block .val{ font-size:13px; color:var(--ink); white-space:pre-wrap; line-height:1.4; }

  .ec-photos{ display:flex; gap:8px; margin-top:10px; flex-wrap:wrap; align-items:flex-end; }
  .ec-photos img{ height:84px; width:auto; max-width:100%; object-fit:contain; border-radius:10px; border:1.5px solid #ecebe1; cursor:pointer; background:#f4f3ea; }

  .ec-actions{ display:flex; gap:8px; margin-top:14px; }
  .ec-actions button{
    flex:1; padding:9px; border-radius:10px; border:none; font-size:12.5px; font-weight:700; cursor:pointer;
  }
  .btn-edit{ background:#eef0e2; color:var(--green-3); }
  .btn-del{ background:#fbe6e4; color:var(--red); }

  /* ---- Modal ---- */
  .modal-overlay{
    display:none; position:fixed; inset:0; background:rgba(20,30,10,0.55); z-index:100;
    align-items:flex-end; justify-content:center;
  }
  .modal-overlay.show{ display:flex; }
  .modal-sheet{
    background:var(--paper); width:100%; max-width:640px; max-height:92vh; overflow-y:auto;
    border-radius:24px 24px 0 0; padding:22px 20px 28px;
  }
  @media (min-width:680px){
    .modal-overlay{ align-items:center; }
    .modal-sheet{ border-radius:22px; max-height:88vh; }
  }
  .modal-head{ display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; }
  .modal-head h2{ margin:0; font-size:18px; font-weight:800; color:var(--ink); }
  .modal-close{ width:32px;height:32px; border-radius:50%; background:#f1f0e8; border:none; font-size:16px; color:#7a7a68; cursor:pointer; }

  .form-section-title{ font-size:12px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px; color:var(--green-3); margin:18px 0 10px; }
  .form-section-title:first-of-type{ margin-top:0; }
  .form-row{ display:grid; grid-template-columns:1fr 1fr; gap:10px; }
  .form-field{ margin-bottom:12px; }
  .form-field label{ display:block; font-size:12px; font-weight:700; color:#5c5b4c; margin-bottom:5px; }
  .form-field input, .form-field textarea, .form-field select{
    width:100%; padding:11px 12px; border-radius:11px; border:1.5px solid #ecebe2;
    background:#fbfaf4; font-size:14px; color:var(--ink); outline:none; font-family:inherit;
  }
  .form-field input:focus, .form-field textarea:focus, .form-field select:focus{ border-color:var(--green-2); background:#fff; }
  .form-field textarea{ resize:vertical; min-height:64px; }

  .photo-add-btn{
    display:flex; align-items:center; justify-content:center; gap:6px;
    border:2px dashed #d8d7c8; border-radius:12px; padding:14px; cursor:pointer;
    color:#8b8a76; font-size:13px; font-weight:700; background:#fbfaf4;
  }
  .photo-preview-grid{ display:flex; gap:8px; flex-wrap:wrap; margin-top:10px; align-items:flex-end; }
  .photo-preview{ position:relative; height:76px; }
  .photo-preview img{ height:100%; width:auto; max-width:140px; object-fit:contain; border-radius:10px; border:1.5px solid #ecebe1; background:#f4f3ea; display:block; }
  .photo-preview .rm{
    position:absolute; top:-6px; right:-6px; width:20px;height:20px; border-radius:50%;
    background:var(--red); color:#fff; border:none; font-size:11px; cursor:pointer; line-height:1;
  }

  .modal-actions{ display:flex; gap:10px; margin-top:20px; }
  .modal-actions button{ flex:1; padding:13px; border-radius:12px; border:none; font-weight:800; font-size:14px; cursor:pointer; }
  .btn-cancel{ background:#f1f0e8; color:#5c5b4c; }
  .btn-save{ background:linear-gradient(160deg, var(--orange-1), var(--orange-2)); color:#fff; }

  .lightbox{ display:none; position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:200; align-items:center; justify-content:center; padding:20px; }
  .lightbox.show{ display:flex; }
  .lightbox img{ max-width:100%; max-height:100%; border-radius:8px; }

  footer{ text-align:center; color:#8b8a76; font-size:12px; margin-top:30px; padding:0 20px; }

  @media (max-width:420px){
    .title-block h1{ font-size:22px; }
    .ec-grid{ grid-template-columns:1fr 1fr; }
    .form-row{ grid-template-columns:1fr; }
  }
</style>
</head>
<body>
<div class="grid-overlay"></div>
<div class="wrap">

  <header>
    <div class="logo-badge">
      <img src="data:image/png;base64," alt="Logo perusahaan">
    </div>
    <div class="title-block">
      <h1>Laporan<span class="accent">Sidak</span></h1>
      <p id="headerSub">Inspeksi Mendadak Area Plantation — PT. Great Giant Pineapple</p>
    </div>
    <div class="menu-wrap">
      <button class="menu-btn" id="menuBtn" type="button" aria-label="Pengaturan laporan">
        <svg id="menuIconDots" viewBox="0 0 24 24" fill="currentColor">
          <circle cx="12" cy="5" r="2"></circle><circle cx="12" cy="12" r="2"></circle><circle cx="12" cy="19" r="2"></circle>
        </svg>
      </button>
      <div class="settings-panel" id="settingsPanel">

        <div id="settingsPanelContent">
          <div class="sp-title">Pengaturan laporan</div>
          <label>Petugas Sidak</label>
          <input id="setPetugas" type="text" value="HRBP, Security , System Mutu">
          <label>Label periode (nama sheet)</label>
          <input id="setPeriode" type="text">
          <label>Lokasi tanda tangan</label>
          <input id="setLokasiTtd" type="text" value="Terbanggi Besar">
          <label>Jabatan Prepared by</label>
          <input id="setRole1" type="text" value="HRBP Wilayah">
          <label>Jabatan Approved by (1)</label>
          <input id="setRole2" type="text" value="People Partner">
          <label>Jabatan Approved by (2)</label>
          <input id="setRole3" type="text" value="Sub-Dep Head">
          <button class="sp-close" id="spClose" type="button">Selesai</button>
        </div>

      </div>
    </div>
  </header>

  <button class="add-btn" id="addBtn" type="button" style="display:none;">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
    Tambah Data Sidak
  </button>

  <div class="card">
    <div class="toolbar">
      <div class="search-box">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"></circle><line x1="21" y1="21" x2="16.5" y2="16.5"></line></svg>
        <input id="searchInput" type="text" placeholder="Cari department, lokasi, mandor, kasie...">
      </div>
      <button class="export-btn" id="exportBtn" type="button">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16V4"></path><path d="M6 10l6 6 6-6"></path><path d="M4 20h16"></path></svg>
        Excel
      </button>
    </div>
    <div class="filter-row">
      <div class="chip active" data-f="all">Semua</div>
      <div class="chip" data-f="Open">Open</div>
      <div class="chip" data-f="Proses">Proses</div>
      <div class="chip" data-f="Selesai">Selesai</div>
    </div>
    <div class="date-filter-row">
      <div class="df-field">
        <label for="filterDate">Filter Tanggal</label>
        <input id="filterDate" type="date">
      </div>
      <div class="df-field">
        <label for="filterMonth">Filter Bulan</label>
        <input id="filterMonth" type="month">
      </div>
      <button class="df-reset" id="filterResetBtn" type="button">Reset</button>
    </div>
  </div>

  <div class="results-head">
    <h3>Hasil Sidak</h3>
    <span id="resultsCount"></span>
  </div>

  <div id="resultsList"></div>

  <footer>LaporanSidak &middot; data tersimpan di database server (MySQL) aplikasi ini.</footer>
</div>

<!-- Add/Edit modal -->
<div class="modal-overlay" id="modalOverlay">
  <div class="modal-sheet">
    <div class="modal-head">
      <h2 id="modalTitle">Tambah Data Sidak</h2>
      <button class="modal-close" id="modalClose" type="button">✕</button>
    </div>

    <div class="form-section-title">Data Utama</div>
    <div class="form-row">
      <div class="form-field"><label>No</label><input id="fNo" type="text"></div>
      <div class="form-field"><label>Tanggal</label><input id="fTanggal" type="date"></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Department</label><input id="fDept" type="text" placeholder="mis. Wilayah 10"></div>
      <div class="form-field"><label>Lokasi</label><input id="fLokasi" type="text" placeholder="mis. 121A"></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Mandor</label><input id="fMandor" type="text"></div>
      <div class="form-field"><label>Kasie</label><input id="fKasie" type="text"></div>
    </div>

    <div class="form-section-title">Temuan &amp; Tindak Lanjut</div>
    <div class="form-field"><label>Temuan</label><textarea id="fTemuan" placeholder="Uraikan temuan hasil sidak..."></textarea></div>
    <div class="form-field"><label>Verifikasi</label><textarea id="fVerifikasi" placeholder="Opsional"></textarea></div>
    <div class="form-row">
      <div class="form-field"><label>Tanggal Verifikasi</label><input id="fTglVerifikasi" type="date"></div>
      <div class="form-field"><label>Status</label>
        <select id="fStatus">
          <option value="">-- Pilih --</option>
          <option value="Open">Open</option>
          <option value="Proses">Proses</option>
          <option value="Selesai">Selesai</option>
        </select>
      </div>
    </div>
    <div class="form-field"><label>Corrective Action</label><textarea id="fCorrective" placeholder="Opsional"></textarea></div>
    <div class="form-field"><label>PIC</label><input id="fPic" type="text"></div>

    <div class="form-section-title">Dokumentasi</div>
    <div class="photo-add-btn" id="photoAddBtn">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" width="17" height="17"><rect x="3" y="3" width="18" height="18" rx="2"></rect><circle cx="9" cy="9" r="2"></circle><path d="M21 15l-5-5L5 21"></path></svg>
      Tambah Foto
    </div>
    <input type="file" id="photoInput" accept="image/*" multiple style="display:none;">
    <div class="photo-preview-grid" id="photoPreviewGrid"></div>

    <div class="modal-actions">
      <button class="btn-cancel" id="btnCancel" type="button">Batal</button>
      <button class="btn-save" id="btnSave" type="button">Simpan</button>
    </div>
  </div>
</div>

<div class="lightbox" id="lightbox"><img id="lightboxImg" src=""></div>

<script>
(function(){
  const LOGO_B64 = "";
  let entries = [];
  let settings = {
    petugas: 'HRBP, Security , System Mutu',
    periode: '',
    lokasiTtd: 'Terbanggi Besar',
    role1: 'HRBP Wilayah',
    role2: 'People Partner',
    role3: 'Sub-Dep Head'
  };
  let isAdmin = true;
  let statusFilter = 'all';
  let dateFilter = '';
  let monthFilter = '';
  let editingId = null;
  let currentPhotos = [];

  // ---- persistence (MySQL via PHP API) ----
  const API_BASE = 'api/';

  async function loadEntries(){
    try{
      const res = await fetch(API_BASE + 'sidak_list.php');
      const json = await res.json();
      entries = json.success ? json.data : [];
    }catch(err){ entries = []; }
  }
  async function loadSettingsFromServer(){
    try{
      const res = await fetch(API_BASE + 'settings_get.php');
      const json = await res.json();
      if(json.success) settings = Object.assign(settings, json.data);
    }catch(err){}
    if(!settings.periode){
      const now = new Date();
      settings.periode = String(now.getMonth()+1).padStart(2,'0') + now.getFullYear();
    }
  }
  let settingsSaveTimer = null;
  function saveSettings(){
    clearTimeout(settingsSaveTimer);
    settingsSaveTimer = setTimeout(async () => {
      try{
        await fetch(API_BASE + 'settings_update.php', {
          method:'POST',
          headers:{ 'Content-Type':'application/json' },
          body: JSON.stringify(settings)
        });
      }catch(err){}
    }, 400);
  }

  // ---- helpers ----
  function uid(){ return 'e' + Date.now().toString(36) + Math.random().toString(36).slice(2,7); }
  function todayLocalISO(){
    const d = new Date();
    const y = d.getFullYear();
    const m = String(d.getMonth()+1).padStart(2,'0');
    const day = String(d.getDate()).padStart(2,'0');
    return y + '-' + m + '-' + day;
  }
  // ExcelJS/Excel serializes JS Date objects using UTC components. A local-midnight
  // Date (e.g. new Date('2026-09-07T00:00:00') in WIB/UTC+7) is internally
  // 2026-09-06T17:00:00Z, so Excel displays the day BEFORE the intended date.
  // Build the Date from UTC components instead so the visible date matches.
  function isoToExcelUtcDate(iso){
    const [y, m, d] = iso.split('-').map(Number);
    return new Date(Date.UTC(y, m - 1, d));
  }
  function escapeHtml(s){ return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
  function fmtDate(iso){
    if(!iso) return '-';
    const d = new Date(iso + 'T00:00:00');
    if(isNaN(d)) return iso;
    const bulan = ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];
    return d.getDate() + ' ' + bulan[d.getMonth()] + ' ' + d.getFullYear();
  }
  function fmtDateLong(d){
    const bulan = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    return d.getDate() + ' ' + bulan[d.getMonth()] + ' ' + d.getFullYear();
  }
  function nextNo(){
    let max = 0;
    entries.forEach(e => { const n = parseInt(e.no,10); if(!isNaN(n) && n > max) max = n; });
    return String(max + 1);
  }

