  btnSave.addEventListener('click', async () => {
    if(!isAdmin) return;
    if(!fDept.value.trim() || !fLokasi.value.trim() || !fMandor.value.trim() || !fTanggal.value){
      alert('Mohon lengkapi minimal Tanggal, Department, Lokasi, dan Mandor.');
      return;
    }
    btnSave.disabled = true;
    const origLabel = btnSave.textContent;
    btnSave.textContent = 'Menyimpan...';
    try{
      const fd = new FormData();
      fd.append('no', fNo.value.trim());
      fd.append('tanggal', fTanggal.value);
      fd.append('department', fDept.value.trim());
      fd.append('lokasi', fLokasi.value.trim());
      fd.append('mandor', fMandor.value.trim());
      fd.append('kasie', fKasie.value.trim());
      fd.append('temuan', fTemuan.value.trim());
      fd.append('verifikasi', fVerifikasi.value.trim());
      fd.append('tglVerifikasi', fTglVerifikasi.value || '');
      fd.append('status', fStatus.value || '');
      fd.append('correctiveAction', fCorrective.value.trim());
      fd.append('pic', fPic.value.trim());

      if(editingId){
        fd.append('id', editingId);
        // Existing (already-saved) photos kept, in their current order.
        currentPhotos.forEach(p => { if(p && p.id){ fd.append('existing_photo_ids[]', p.id); } });
      }
      // Newly added photos (not yet on the server) get uploaded as files.
      currentPhotos.forEach(p => {
        if(!(p && p.id)){
          const dataUrl = photoUrl(p);
          fd.append('new_photos[]', dataUrlToBlob(dataUrl), 'photo.jpg');
        }
      });

      const endpoint = API_BASE + (editingId ? 'sidak_update.php' : 'sidak_create.php');
      const res = await fetch(endpoint, { method:'POST', body: fd });
      const json = await res.json();
      if(!json.success) throw new Error(json.message || 'Gagal menyimpan data');

      closeModal();
      await loadEntries();
      renderList();
    }catch(err){
