  // ---- Excel export (matches PT GGP Sidak template) ----
  function dataUrlToBase64(dataUrl){
    return dataUrl.split(',')[1];
  }
  function estimateTextRowHeight(entry){
    const fields = [entry.temuan, entry.verifikasi, entry.correctiveAction];
    let maxLines = 1;
    fields.forEach(f => {
      if(!f) return;
      const lines = f.split('\n').length + Math.floor(f.length / 40);
      if(lines > maxLines) maxLines = lines;
    });
    return Math.max(60, Math.min(220, 30 + maxLines * 15));
  }

  async function exportToExcel(){
    if(entries.length === 0){
      alert('Belum ada data untuk di-export.');
      return;
    }
    exportBtn.disabled = true;
    const origLabel = exportBtn.innerHTML;
    exportBtn.innerHTML = 'Membuat...';

    try{
      const wb = new ExcelJS.Workbook();
      const sheetName = (settings.periode || '082026').slice(0,31);
      const ws = wb.addWorksheet(sheetName, { pageSetup:{ orientation:'landscape', paperSize:9 } });

      const cols = ['','No','Department','Tanggal','Lokasi','Mandor','Kasie','Temuan','Verifikasi','Tanggal Verifikasi','Corective Action','Dokumentasi','PIC','Status'];
      const widths = [3,6,22,17,20,20,20,45,30,16,32,44,14,14];
      widths.forEach((w,i) => { ws.getColumn(i+1).width = w; });

      // Logo (top-left, columns B:C, rows 1-3 — matches original template layout)
      ws.mergeCells(1,2,3,3);
      ws.getRow(1).height = 28; ws.getRow(2).height = 28;
      try{
        const logoId = wb.addImage({ base64: LOGO_B64, extension: 'png' });
        ws.addImage(logoId, {
          tl: { col: 2.25, row: 0.06 },
          ext: { width: 68, height: 74 }
        });
      }catch(err){}

      // Title (columns D:N, rows 1-2)
      ws.mergeCells(1,4,2,14);
      const titleCell = ws.getCell(1,4);
      titleCell.value = 'PT. GREAT GIANT PINEAPPLE\nINSPEKSI MENDADAK AREA PLANTATION';
      titleCell.font = { name:'Calibri', size:12, bold:true };
      titleCell.alignment = { horizontal:'center', vertical:'middle', wrapText:true };

      ws.mergeCells(3,4,3,14);
      const petugasCell = ws.getCell(3,4);
      petugasCell.value = 'Petugas Sidak : ' + settings.petugas;
      petugasCell.font = { name:'Calibri', size:10, bold:true };
      petugasCell.alignment = { horizontal:'left', vertical:'middle', wrapText:true };
      ws.getRow(3).height = 20;

      // Header row
      const headerRowIdx = 4;
      const headerRow = ws.getRow(headerRowIdx);
      for(let c=2; c<=14; c++){
        const cell = ws.getCell(headerRowIdx, c);
        cell.value = cols[c-1];
        cell.font = { name:'Calibri', size:10, bold:true };
        cell.alignment = { horizontal:'center', vertical:'middle', wrapText:true };
        cell.border = { top:{style:'thin'}, left:{style:'thin'}, bottom:{style:'thin'}, right:{style:'thin'} };
      }
      headerRow.height = 26;

      // Data rows
      let r = headerRowIdx + 1;
      const sortedForExport = entries.slice().sort((a,b) => (a.tanggal||'').localeCompare(b.tanggal||''));
      for(const e of sortedForExport){
        const rowVals = [null, e.no, e.department, e.tanggal ? isoToExcelUtcDate(e.tanggal) : '', e.lokasi, e.mandor, e.kasie, e.temuan, e.verifikasi, e.tglVerifikasi ? isoToExcelUtcDate(e.tglVerifikasi) : '', e.correctiveAction, '', e.pic, e.status];
        for(let c=2; c<=14; c++){
          const cell = ws.getCell(r, c);
          cell.value = rowVals[c-1];
          cell.font = { name:'Calibri', size:10 };
          cell.alignment = { horizontal:'center', vertical:'middle', wrapText:true };
          cell.border = { top:{style:'thin'}, left:{style:'thin'}, bottom:{style:'thin'}, right:{style:'thin'} };
          if(c === 4 || c === 10){ cell.numFmt = 'dd/mm/yyyy'; }
        }
        // Dokumentasi column (col 12 / L): resolve photo sizes FIRST, so the row
        // grows/shrinks to match the photo's own aspect ratio at full column width,
        // instead of squeezing the photo into a preset box.
        const dokumentasiColIdx = 11; // 0-indexed column for "L" (Dokumentasi)
        const cellWpx = widths[dokumentasiColIdx] * 7;
        const pad = 5;
        const gap = 6;
        const textRh = estimateTextRowHeight(e);
        let finalRh = textRh;
        let photoLayout = [];

        if(e.photos && e.photos.length){
          // Show EVERY photo (not just the first two), wrapped 2-per-row inside
          // the cell. Each photo keeps its own aspect ratio at the slot width,
          // and the row height grows to fit however many photo-rows are needed.
          const perRow = 2;
          let cursorY = pad;

          for(let pi=0; pi<e.photos.length; pi+=perRow){
            const rowPhotos = e.photos.slice(pi, pi + perRow);
            // Size slots for THIS row based on how many photos are actually in it:
            // a lone photo (e.g. only 1 total, or the odd one left over) fills the
            // whole column width instead of being squeezed into a half-width slot.
            const rowCount = rowPhotos.length;
            const availWRow = cellWpx - pad*2 - gap*(rowCount-1);
            const slotWRow = availWRow / rowCount;
            let rowImgs = [];
            let rowMaxH = 0;
            for(let j=0; j<rowPhotos.length; j++){
              const photoObj = rowPhotos[j];
              const rawUrl = photoUrl(photoObj);
              let nw, nh;
              if(photoObj && typeof photoObj === 'object' && photoObj.width){
                nw = photoObj.width; nh = photoObj.height;
              } else {
                const sz = await loadImageSize(rawUrl);
                nw = sz.width; nh = sz.height;
              }
              // photos stored on the server are plain URLs; ExcelJS needs a data URL,
              // so fetch and convert them to base64 only at export time (not stored).
              const dataUrl = rawUrl.startsWith('data:') ? rawUrl : await urlToDataUrl(rawUrl);
              // fill the slot's full width; height follows the photo's own aspect ratio
              const imgW = slotWRow;
              const imgH = nh * (slotWRow / nw);
              if(imgH > rowMaxH) rowMaxH = imgH;
              rowImgs.push({ dataUrl, imgW, imgH, slotX: pad + j*(slotWRow + gap) });
            }
            rowImgs.forEach(im => {
              photoLayout.push({ dataUrl: im.dataUrl, imgW: im.imgW, imgH: im.imgH,
                slotX: im.slotX, offY: cursorY + (rowMaxH - im.imgH) / 2 });
            });
            cursorY += rowMaxH + gap;
          }

          const totalHpx = cursorY - gap + pad; // drop trailing gap, add bottom padding
          const photoRhPoints = totalHpx / 1.33;
          finalRh = Math.max(textRh, Math.min(1000, photoRhPoints));
        }

        ws.getRow(r).height = finalRh;
        const cellHpx = finalRh * 1.33;

        for(const p of photoLayout){
          try{
            const offX = p.slotX;
            const offY = p.offY;
            const ext = p.dataUrl.substring(p.dataUrl.indexOf('/')+1, p.dataUrl.indexOf(';'));
            const imgId = wb.addImage({ base64: p.dataUrl, extension: ext === 'jpeg' ? 'jpeg' : 'png' });
            ws.addImage(imgId, {
              tl: { col: dokumentasiColIdx + offX/cellWpx, row: (r-1) + offY/cellHpx },
              ext: { width: p.imgW, height: p.imgH }
            });
          }catch(err){}
        }
        r++;
      }

      // Signature section
      r += 1;
      ws.getCell(r,2).value = (settings.lokasiTtd || 'Terbanggi Besar') + ', ' + fmtDateLong(new Date());
      ws.getCell(r,2).font = { name:'Calibri', size:11 };
      r += 1;
      ws.getCell(r,2).value = 'Prepared by,';
      ws.getCell(r,2).font = { name:'Calibri', size:11 };
      ws.getCell(r,8).value = 'Approved by,';
      ws.getCell(r,8).font = { name:'Calibri', size:11 };
      ws.getCell(r,8).alignment = { horizontal:'center' };
      ws.getCell(r,10).value = 'Approved by,';
      ws.getCell(r,10).font = { name:'Calibri', size:11 };
      const signLabelRow = r;
      r += 4;
      ws.getCell(r,2).value = settings.role1;
      ws.getCell(r,2).font = { name:'Calibri', size:11 };
      ws.getCell(r,8).value = settings.role2;
      ws.getCell(r,8).font = { name:'Calibri', size:11 };
      ws.getCell(r,8).alignment = { horizontal:'center' };
      ws.getCell(r,10).value = settings.role3;
      ws.getCell(r,10).font = { name:'Calibri', size:11 };

      ws.pageSetup.printArea = `B1:N${r}`;

      const buffer = await wb.xlsx.writeBuffer();
      const blob = new Blob([buffer], { type: 'application/octet-stream' });
      saveAs(blob, `Sidak_${settings.periode || 'laporan'}.xlsx`);
    }catch(err){
      alert('Gagal membuat file Excel: ' + err.message);
    }finally{
      exportBtn.disabled = false;
      exportBtn.innerHTML = origLabel;
    }
  }
  exportBtn.addEventListener('click', exportToExcel);

  // ---- init ----
  (async function init(){
    applyAdminUI();
    await loadSettingsFromServer();
    await loadEntries();
    renderList();
  })();
})();
</script>
</body>
</html>
